FIXES[432] = {"prompt": "A CloudFormation stack installs Active Directory, SQL Server and SharePoint components on EC2. The stack must not finish creating an instance until application installation and configuration have succeeded. Which configuration should be used?", "options": ["Configure UpdateReplacePolicy and send a success signal using cfn-signal after configuration.", "Configure a CreationPolicy on the instance and send a success signal using cfn-signal after configuration.", "Configure DependsOn and send a success signal using cfn-init after configuration.", "Configure UpdatePolicy on the instance and send a success signal using cfn-signal after configuration."]}
