def remap(index, reference, order):
    """Explicitly reviewed option-order variant; order maps new positions to old ones."""
    review = REVIEWS[reference]
    assert sorted(order) == list(range(len(review["explanations"])))
    REVIEWS[index] = {**review, "correct": [i for i, old in enumerate(order) if old in review["correct"]], "explanations": [review["explanations"][old] for old in order]}


