FIXES[46] = {"options": ["CREATE USER iam_db_user IDENTIFIED WITH AWSAuthenticationPlugin;", "CREATE USER iam_db_user_plugin;", "Rename the IAM user as a database user.", "CREATE USER iam_db_user IDENTIFIED WITH AWSAuthenticationPlugin AS 'RDS';"]}
