FIXES[194] = {"prompt": "Administrators perform AWS Organizations management actions. Which service can match supported recorded API events and route notifications to subscribed stakeholders?", "options": ["Amazon EventBridge", "AWS Config resources", "AWS CloudTrail", "Amazon CloudWatch Logs"]}
