FIXES[207] = {"prompt": "An application uses a TLS Network Load Balancer with supported instance/IP targets, including IP targets for on-premises hosts. Its access logs are in S3. Which choice most simply analyzes many logs for clients with slow TLS handshakes without adding visualization?"}
